       jsonb_build_object('timeouts_15m', count(*), 'jobs', coalesce(jsonb_agg(distinct j.jobname), '[]'),
         'severity', case when count(*) >= (select one.threshold('cron_startup_timeouts_p1_15m')) then 'P1' else 'P2' end) as value
